func WithHistory(name string, next Handler) Handler {
	return func(ctx context.Context, m kafka.Message) error {
		hops := decodeHistory(headerValue(m.Headers, "history"))
		hops = append(hops, Hop{Name: name, At: time.Now().UTC()})
		m.Headers = setHeader(m.Headers, "history", encodeHistory(hops))
		return next(ctx, m)
	}
}
